--
-- Table structure for table `farmer`
--

DROP TABLE IF EXISTS `farmer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `farmer` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `firstname` varchar(255) NOT NULL,
  `lastname` varchar(255) NOT NULL,
  `othername` varchar(255) DEFAULT NULL,
  `product_farmed` text DEFAULT NULL,
  `location_of_farm` varchar(255) DEFAULT NULL,
  `size_of_farm` varchar(255) DEFAULT NULL,
  `phone_no` varchar(255) NOT NULL,
  `bvn` varchar(255) DEFAULT NULL,
  `account_name` varchar(255) DEFAULT NULL,
  `account_no` varchar(255) DEFAULT NULL,
  `nin` varchar(255) DEFAULT NULL,
  `date_of_birth` varchar(255) DEFAULT NULL,
  `gender` varchar(255) DEFAULT NULL,
  `level_of_education` varchar(255) DEFAULT NULL,
  `user_id` int(11) DEFAULT NULL,
  `state_id` int(11) DEFAULT NULL,
  `lg_id` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `source_type` varchar(255) DEFAULT NULL,
  `address_of_farm` text DEFAULT NULL,
  `farm_size` text DEFAULT NULL,
  `village` varchar(255) DEFAULT NULL,
  `ward` varchar(255) DEFAULT NULL,
  `profile_pic` text DEFAULT NULL,
  `farm_size_measurement` varchar(255) DEFAULT NULL,
  `referee` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_id` (`user_id`),
  KEY `state_id` (`state_id`),
  KEY `lg_id` (`lg_id`),
  KEY `farmer_referee_foreign_idx` (`referee`),
  CONSTRAINT `farmer_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`),
  CONSTRAINT `farmer_ibfk_2` FOREIGN KEY (`state_id`) REFERENCES `states` (`id`),
  CONSTRAINT `farmer_ibfk_3` FOREIGN KEY (`lg_id`) REFERENCES `lgas` (`id`),
  CONSTRAINT `farmer_referee_foreign_idx` FOREIGN KEY (`referee`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6024 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

