--
-- Table structure for table `transaction_log`
--

DROP TABLE IF EXISTS `transaction_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `transaction_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `farmer_id` int(11) DEFAULT NULL,
  `transaction_ref` varchar(255) NOT NULL,
  `currency` varchar(255) DEFAULT NULL,
  `amount` double DEFAULT NULL,
  `description` text DEFAULT NULL,
  `company_id` int(11) DEFAULT NULL,
  `status` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `transaction_id` varchar(255) DEFAULT NULL,
  `pickup_point` text DEFAULT NULL,
  `seedtrader_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `transaction_ref` (`transaction_ref`),
  KEY `farmer_id` (`farmer_id`),
  KEY `company_id` (`company_id`),
  KEY `transaction_log_seedtrader_id_foreign_idx` (`seedtrader_id`),
  CONSTRAINT `transaction_log_ibfk_1` FOREIGN KEY (`farmer_id`) REFERENCES `farmer` (`id`),
  CONSTRAINT `transaction_log_ibfk_2` FOREIGN KEY (`company_id`) REFERENCES `seedcompany` (`id`),
  CONSTRAINT `transaction_log_seedtrader_id_foreign_idx` FOREIGN KEY (`seedtrader_id`) REFERENCES `seedtrader` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=113 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

